use std::{collections::HashSet,fs};
use lex_core::Provision;
fn main(){
 let all:Vec<Provision>=serde_json::from_str(&fs::read_to_string("/Users/jr/Dev/lex-mex/corpus/mx/lritf/provisions.json").unwrap()).unwrap();
 for text in ["Se aplicará el artículo 999 de esta Ley.","Se aplicará el artículo anterior de la Constitución Política de los Estados Unidos Mexicanos.","Se aplicarán los artículos 1 a 3 de esta Ley."] {
  let mut ps=all[..3].to_vec();ps[1].text=text.into();
  let edges=lex_parse::extract_internal_references(&ps).unwrap();
  println!("INPUT: {text}");for e in edges.iter().filter(|e|e.source_provision_id==ps[1].id){println!("{} -> {} {:?}",e.source_span,e.target_provision_id,e.resolution_status);}
  if text.contains("999") {let report=lex_parse::validate_lritf(&ps,&edges,3,0);println!("VALID={} issues={:?}",report.valid,report.issues);}
 }
 let mut ps=all[..3].to_vec();ps[1].text="Se aplicará el artículo anterior de la Constitución Política de los Estados Unidos Mexicanos.".into();
 let opts=lex_parse::ReferenceOptions{policy:lex_parse::InstrumentContextPolicy::SentenceEarliestMarker{internal_markers:vec!["de esta ley".into()],external_instruments:vec![("constitución política de los estados unidos mexicanos".into(),"urn:lex-mx:federal:constitution:cpeum".into())]},transitory_citations:true,same_article_fractions:true,relative_references:true,historical_targets:vec![]};
 let refs=lex_parse::extract_references(&ps,None,&opts,&ps.iter().map(|p|p.id.clone()).collect()).unwrap();println!("CROSS-INSTRUMENT POLICY relative: {:?}",refs.iter().filter(|e|e.source_provision_id==ps[1].id).map(|e|(&e.source_span,&e.target_provision_id)).collect::<Vec<_>>());
 let mut ps=all[..3].to_vec();ps[1].text="Se aplicará el artículo 1 de esta Ley.".into();
 let mut edges=lex_parse::extract_internal_references(&ps).unwrap();edges.retain(|e|e.source_provision_id==ps[1].id);
 let e=&mut edges[0];e.target_instrument_id="urn:lex-mx:federal:constitution:cpeum".into();e.target_provision_id="urn:lex-mx:federal:statute:lga:article:1".into();
 let external=HashSet::from([e.target_provision_id.clone()]);
 let report=lex_parse::validate_corpus(&lex_parse::CorpusView{instrument_id:&ps[0].instrument_id,official_title:None,provisions:&ps,references:&edges,terms:&[],term_usages:&[],amendment_references:&[]}, &lex_parse::CorpusExpectations{articles:Some(3),transitories:Some(0),..Default::default()},&external,&HashSet::new());
 println!("MISOWNED_TARGET {} claims {}: VALID={} issues={:?}",edges[0].target_provision_id,edges[0].target_instrument_id,report.valid,report.issues);
}

