use chrono::NaiveDate;
use lex_parse::{DiputadosOptions,parse_diputados};
fn main(){
 let raw="Artículo 1. Texto propio.

TRANSITORIOS

PRIMERO. Cierre propio.

ANEXO 1. Cuadro legal

Contenido inicial conservado.

La nota cita ARTÍCULOS TRANSITORIOS DE DECRETOS DE REFORMA como contenido del cuadro.

CONTENIDO FINAL QUE DEBE CONSERVARSE.
";
 let options=DiputadosOptions{instrument_id:"urn:lex-mx:federal:statute:audit".to_owned(),header_lines:vec![],stop_markers:vec![],annex_markers:vec!["ANEXO 1.".to_owned()],separate_enactment:false,nested_instrument:None};
 let doc=parse_diputados(raw,&options,NaiveDate::from_ymd_opt(2026,1,1).unwrap()).unwrap();
 for p in doc.provisions {println!("{:?}: {} => {}",p.provision_type,p.label,p.text);}
}
